  if (!state) return;
  const now = Date.now();
  const active = [...state.inFlight.entries()].map(([name, entry]: any) => ({
    name,
    elapsedMs: Math.max(0, now - Number(entry.startedAt)),
    expectedMs: Number(entry.expectedMs),
    fraction: Math.min(0.9, Math.max(0, (now - Number(entry.startedAt)) / Math.max(1, Number(entry.expectedMs)))),
  }));
  const completed = state.completed.size;
