  const line = `[validators:${state.profile}:progress] schema=${VALIDATOR_PROGRESS_SCHEMA_ID} runId=${state.runId} percent=${percent} completed=${completed}/${state.total} batch=${state.batchIndex}/${state.batchCount} phase=${phase} active=${activeText}\n`;
